# Follow existing plot_public_cd40.R and figures_r/common.R publication conventions.
args<-commandArgs(trailingOnly=TRUE);ROOT<-normalizePath(args[1])
DATA<-file.path(ROOT,'papers/01_mr_imaging_scan/results/new_scan_regions_20261117');OUT<-file.path(DATA,'figures')
source(file.path(ROOT,'papers/01_mr_imaging_scan/figures_r/common.R'))
stopifnot(isTRUE(fromJSON(file.path(DATA,'INDEPENDENT_VERIFICATION.json'))$complete))
dir.create(OUT,recursive=TRUE,showWarnings=FALSE);dir.create(file.path(OUT,'qa'),showWarnings=FALSE);dir.create(file.path(OUT,'plot_data'),showWarnings=FALSE)
batch<-read.csv(file.path(DATA,'batch_regions.csv'));batch$gene<-factor(batch$gene,levels=batch$gene)
regional<-list();shared<-list()
for(i in seq_len(nrow(batch))){
 rec<-batch[i,];folder<-file.path(ROOT,'data/new_scan_regional_20261117',rec$accession)
 x<-read.csv(gzfile(file.path(folder,'regional_statistics.csv.gz')));y<-read.csv(gzfile(file.path(folder,'imaging_region_GRCh37.csv.gz')))
 regional[[length(regional)+1]]<-data.frame(gene=rec$gene,relative_kb=(x$base_pair_location-rec$center)/1000,z=abs(x$beta/x$standard_error),source='AGES protein')
 regional[[length(regional)+1]]<-data.frame(gene=rec$gene,relative_kb=(y$base_pair_location-rec$center)/1000,z=abs(y$beta/y$standard_error),source='Oxford imaging')
 d<-read.csv(gzfile(file.path(DATA,rec$accession,'shared_snps.csv.gz')))
 shared[[i]]<-data.frame(gene=rec$gene,z_protein=abs(d$beta_x/d$standard_error_x),z_imaging=abs(d$beta_y/d$standard_error_y),relative_kb=(d$pos37-rec$center)/1000)
}
regional<-do.call(rbind,regional);regional$gene<-factor(regional$gene,levels=batch$gene);regional$source<-factor(regional$source,levels=c('AGES protein','Oxford imaging'));shared<-do.call(rbind,shared);shared$gene<-factor(shared$gene,levels=batch$gene)
a<-ggplot(regional,aes(relative_kb,z))+geom_point(size=.2,alpha=.45,stroke=0,colour='#758AA2')+geom_vline(xintercept=0,colour='#BBBBBB',linewidth=.3/.pt,linetype='dashed')+facet_wrap(source~gene,ncol=3,scales='free_y',labeller=labeller(gene=c('LRRC37A2'='LRRC37A2 | 1763: left ALIC L3','MRC1'='MRC1 | 1441: right caudate T2*','CGREF1'='CGREF1 | 2046: left SLF OD')))+scale_x_continuous(breaks=c(-1000,0,1000),labels=c('−1000','0','1000'))+labs(x='Position relative to the new-MR sentinel (GRCh37, kb)',y='Absolute association z')+theme(panel.spacing.x=unit(4,'mm'),panel.spacing.y=unit(2,'mm'))
b<-ggplot(shared,aes(z_protein,z_imaging,colour=relative_kb))+geom_point(size=.25,alpha=.6,stroke=0)+facet_wrap(~gene,nrow=1,scales='free')+scale_colour_gradientn(colours=c('#719DB9','#E5E5E5','#A66868'),name='Relative position (kb)')+guides(colour=guide_colourbar(display='rectangles'))+labs(x='AGES protein absolute z',y='Imaging absolute z')+theme(legend.position='bottom',legend.key.width=unit(5,'mm'),panel.spacing=unit(2,'mm'))
s<-read.csv(file.path(DATA,'coloc_prior_sensitivity.csv'),check.names=FALSE);prior<-rbind(transform(s,hypothesis='H3: distinct',posterior=PP.H3.abf),transform(s,hypothesis='H4: shared',posterior=PP.H4.abf));prior$gene<-factor(prior$gene,levels=batch$gene);prior$window<-factor(ifelse(prior$window_bp==500000,'500 kb','1 Mb'),levels=c('500 kb','1 Mb'))
c<-ggplot(prior,aes(p12_requested,posterior,colour=hypothesis,linetype=window))+geom_vline(xintercept=1e-5,colour='#CCCCCC',linewidth=.3/.pt)+geom_line(linewidth=.6/.pt)+scale_x_log10(breaks=c(1e-6,1e-5,3e-5),labels=c('1e−6','1e−5','3e−5'))+scale_y_continuous(limits=c(0,1),breaks=c(0,.5,1),expand=expansion(mult=c(.01,.02)))+scale_colour_manual(values=c('H3: distinct'='#A66868','H4: shared'='#3A8B84'))+scale_linetype_manual(values=c('solid','dashed'))+facet_wrap(~gene,nrow=1)+labs(x='Shared-variant prior',y='Posterior probability',colour=NULL,linetype=NULL)+theme(legend.position='bottom',legend.box='vertical',legend.margin=margin(0,0,0,0),axis.text.x=element_text(angle=45,hjust=1,vjust=1),panel.spacing=unit(3,'mm'))
reverse<-read.csv(file.path(ROOT,'papers/01_mr_imaging_scan/results/new_scan_reverse_20261117/reverse_direction_estimates.csv'));reverse$gene<-factor(reverse$gene,levels=batch$gene);reverse$row<-paste(ifelse(reverse$imaging_effect_set=='discovery','Discovery','Replication'),reverse$palindrome_policy,sep=' / ');reverse$row<-factor(reverse$row,levels=rev(c('Discovery / drop','Replication / drop','Discovery / infer','Replication / infer')))
reverse$outer_low<-ifelse(reverse$n_instruments>1,reverse$ci_lower_random,reverse$ci_lower_delta);reverse$outer_high<-ifelse(reverse$n_instruments>1,reverse$ci_upper_random,reverse$ci_upper_delta)
labelpos<-aggregate(cbind(outer_low,outer_high)~gene,reverse,function(x)c(min=min(x),max=max(x)));reverse$label_x<-NA_real_
for(g in levels(reverse$gene)){ix<-reverse$gene==g;lo<-min(reverse$outer_low[ix]);hi<-max(reverse$outer_high[ix]);span<-hi-lo;reverse$label_x[ix]<-hi+.12*span}
d<-ggplot(reverse,aes(x=beta,y=row))+geom_vline(xintercept=0,colour='#BBBBBB',linewidth=.3/.pt)+geom_segment(aes(x=outer_low,xend=outer_high,yend=row),linewidth=.45/.pt,colour='#758AA2')+geom_segment(aes(x=ci_lower,xend=ci_upper,yend=row),linewidth=1.2/.pt,colour='#3A8B84')+geom_point(size=1.15,colour=INK)+geom_text(aes(x=label_x,label=paste0('k=',n_instruments)),size=6/.pt,hjust=0,family='Arial')+facet_wrap(~gene,nrow=1,scales='free_x')+scale_x_continuous(expand=expansion(mult=c(.04,.25)))+labs(x='AGES protein effect per imaging SD (reported protein units)',y=NULL)+theme(panel.spacing=unit(4,'mm'))
panels<-list(a,b,c,d);layout<-data.frame(id=c('a','b','c','d'),x=c(1,1,89,1),y=c(1,80,80,151),w=c(172,84,84,172),h=c(75,68,68,68),title=c('Full regional associations: first public batch','Shared SNP association patterns','Regional and prior sensitivity','Reverse direction: imaging to protein'))
grobs<-list()
for(i in seq_len(nrow(layout))){rec<-layout[i,];ragg::agg_capture(width=rec$w,height=rec$h,units='mm',res=300);g<-ggplotGrob(panels[[i]]);dev.off();g<-gTree(children=gList(g,txt(rec$id,.6,.8,8,'bold'),txt(rec$title,4.6,1.2,6.5,'bold')));audit<-text_audit(g);stopifnot(all(audit$pt>=6-1e-6));write.csv(audit,file.path(OUT,'qa',paste0('text_',rec$id,'.csv')),row.names=FALSE);grobs[[i]]<-g}
draw<-function(){grid.newpage();for(i in seq_len(nrow(layout))){rec<-layout[i,];pushViewport(viewport(x=unit(rec$x,'mm'),y=unit(225-rec$y,'mm'),width=unit(rec$w,'mm'),height=unit(rec$h,'mm'),just=c('left','top')));grid.draw(grobs[[i]]);popViewport()};grid.text('Thin intervals: random-error IVW or delta Wald; thick: first-order. External EUR LD.',x=unit(4,'mm'),y=unit(2.5,'mm'),just='left',gp=gpar(fontfamily='Arial',fontsize=6))}
open_pdf(file.path(OUT,'New_scan_public_regions.pdf'),174,225);draw();dev.off()
for(dpi in c(600,150)){name<-if(dpi==600)'New_scan_public_regions.png' else 'New_scan_public_regions_preview.png';ragg::agg_png(file.path(OUT,name),width=174,height=225,units='mm',res=dpi,background='white');draw();dev.off()}
for(n in c('regional','shared','prior','reverse'))write.csv(get(n),file.path(OUT,'plot_data',paste0(n,'.csv')),row.names=FALSE)
write.csv(layout,file.path(OUT,'qa/layout_mm.csv'),row.names=FALSE);writeLines(capture.output(sessionInfo()),file.path(OUT,'qa/R_sessionInfo.txt'))
write_json(list(page_mm=c(174,225),panels=4,plotting_areas=15,minimum_font_pt=6,simple_bar_charts=0,regional_rows=nrow(regional),shared_points=nrow(shared),prior_rows=nrow(prior),reverse_rows=nrow(reverse),colour_is_position_not_LD=TRUE,scope='First public acquisition batch; not candidate acceptance. Single-causal ABF with estimated AGES protein SD. Gene-labelled assays are not established equivalents across platforms.',visual_inspection_required=TRUE),file.path(OUT,'qa/FIGURE_AUDIT.json'),auto_unbox=TRUE,pretty=TRUE)
